# Manager 派發 ➔ Worker 執行 ➔ Review 審查迴圈
def manager_node(state):
    task = plan_subtask(state.goal)
    return {"next_worker": "coder", "subtask": task}

def coder_worker(state):
    code = generate_code(state.subtask)
    return {"draft_code": code}

def critic_node(state):
    is_passed = audit_code(state.draft_code)
    return "end" if is_passed else "coder"
